using Microsoft.Extensions.DependencyInjection;
var services = new ServiceCollection();
services.AddScoped<Marker>();
using var provider = services.BuildServiceProvider(new ServiceProviderOptions { ValidateScopes = true });
using var scope1 = provider.CreateScope();
using var scope2 = provider.CreateScope();
var first = scope1.ServiceProvider.GetRequiredService<Marker>();
var second = scope1.ServiceProvider.GetRequiredService<Marker>();
var other = scope2.ServiceProvider.GetRequiredService<Marker>();
Console.WriteLine(ReferenceEquals(first, second));
Console.WriteLine(ReferenceEquals(first, other));
class Marker { }

