using Microsoft.Extensions.DependencyInjection;
var services=new ServiceCollection();services.AddTransient<Transient>();services.AddScoped<Scoped>();services.AddSingleton<Singleton>();
using(var provider=services.BuildServiceProvider(new ServiceProviderOptions{ValidateScopes=true,ValidateOnBuild=true}))
{
 using var a=provider.CreateScope();using var b=provider.CreateScope();
 Console.WriteLine(ReferenceEquals(a.ServiceProvider.GetRequiredService<Transient>(),a.ServiceProvider.GetRequiredService<Transient>()));
 Console.WriteLine(ReferenceEquals(a.ServiceProvider.GetRequiredService<Scoped>(),a.ServiceProvider.GetRequiredService<Scoped>()));
 Console.WriteLine(ReferenceEquals(a.ServiceProvider.GetRequiredService<Scoped>(),b.ServiceProvider.GetRequiredService<Scoped>()));
 Console.WriteLine(ReferenceEquals(a.ServiceProvider.GetRequiredService<Singleton>(),b.ServiceProvider.GetRequiredService<Singleton>()));
}
var invalid=new ServiceCollection();invalid.AddScoped<Scoped>();invalid.AddSingleton<Bad>();
try{using var _=invalid.BuildServiceProvider(new ServiceProviderOptions{ValidateScopes=true,ValidateOnBuild=true});}
catch(AggregateException){Console.WriteLine("captive dependency");}
